import{_ as o,o as t,c as a,ae as n}from"./chunks/framework.Dn6zxbF8.js";const f=JSON.parse('{"title":"Chrono","description":"","frontmatter":{"name":"Chrono","quadrant":"languages-and-frameworks","history":[{"edition":"2026.3","ring":"hold"}],"tags":["rust","datetime","time-zones"]},"headers":[],"relativePath":"radar/items/chrono.md","filePath":"radar/items/chrono.md"}'),r={name:"radar/items/chrono.md"};function i(s,e,d,c,h,l){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="chrono" tabindex="-1">Chrono <a class="header-anchor" href="#chrono" aria-label="Permalink to &quot;Chrono&quot;">​</a></h1><p>Chrono has been the default date and time crate in Rust for most of the language&#39;s life, and it did that job: a timezone-aware <code>DateTime</code>, <code>strftime</code> style formatting, and chrono-tz for the IANA database.</p><p>It is on Hold because its maintainer is winding it down. In <a href="https://github.com/chronotope/chrono/issues/1768" target="_blank" rel="noreferrer">chronotope/chrono#1768</a> chrono and chrono-tz were declared soft-deprecated and unlikely to merge further changes, with the API described as dated and too costly to revise. chrono-tz will no longer follow time zone database releases, which means zoned results drift from reality the next time a government moves a clock. A RustSec unmaintained advisory is planned once <a href="./jiff.html">Jiff</a> reaches 1.0.</p><p>Hold is not a removal order. Code using Chrono keeps working, and a dependency pulling it in transitively is not a reason to fork anything. New code should not add it, and Jiff is the candidate being assessed to replace it.</p>',4)])])}const p=o(r,[["render",i]]);export{f as __pageData,p as default};
